t. Trade with the villagers from your <button class="link-btn" data-goto="inventory">inventory</button>. A generous deed may open a better bargain than a full purse.</p></section>`;el('#mainContent').onclick=e=>{let b=e.target.closest('[data-guild]');if(b){let g=guilds.find(x=>x.id===b.dataset.guild);s.joined.push(g.id);pushLog('faction',`You joined ${g.name}.`);gainXP(15);toast(`Joined ${g.name}.`);render()}let o=e.target.closest('[data-offer]');if(o){let g=gods[+o.dataset.offer][0];s.offering=g;s.deeds.faith=(s.deeds.faith||0)+1;s.gold=Math.max(0,s.gold-1);s.relations.Rowan=Math.min(5,(s.relations.Rowan||0)+1);gainXP(12);pushLog('faith',`You left a silver mark for ${g}.`);toast('Your offering is remembered.');render()}if(e.target.closest('[data-goto]')){s.tab='inventory';render()}}}
