51: window.openCreator=()=>{el('#modalRoot').innerHTML=`<div class="modal-backdrop"><div class="modal"><div class="modal-kicker">The first page</div><h1>Who will you become?</h1><p class="modal-intro">Make a person, not a build. Your choices shape your gifts; your actions will reveal a calling in time.</p><label class="form-label">Name</label><input id="charName" type="text" maxlength="24" placeholder="What shall the world call you?" value="${esc(s.name||'')}"/><label class="form-label">Ancestry</label><div class="options" id="ancestryOptions">${Object.entries(ancestry).map(([k,v])=>`<button class="option ${s.ancestry===k?'selected':''}" data-ancestry="${k}">${k}<small>${v}</small></button>`).join('')}</div><label class="form-label">A life before the road</label><div class="options" id="backgroundOptions">${[['Wanderer','You learned by going.'],['Apprentice','You learned by making.'],['Acolyte','You learned by listening.'],['Courtier','You learned by reading a room.'],['Outcast','You learned to endure.']].map(([k,v])=>`<button class="option ${s.background===k?'selected':''}" data-bg="${k}">${k}<small>${v}</small></button>`).join('')}</div><label class="form-label">Choose two practiced skills</label><div class="options" id="skillOptions">${skills.map(x=>`<button class="option ${s.skills.includes(x)?'selected':''}" data-skill="${x}">${x}</button>`).join('')}</div><div class="modal-actions"><span>All paths begin at level 1. No class is chosen.</span><button class="primary" id="createChar">Enter the Greenmarch →</button></div></div></div>`;
52:  el('#ancestryOptions').onclick=e=>{let b=e.target.closest('[data-ancestry]');if(!b)return;s.ancestry=b.dataset.ancestry;document.querySelectorAll('[data-ancestry]').forEach(x=>x.classList.toggle('selected',x===b))};el('#backgroundOptions').onclick=e=>{let b=e.target.closest('[data-bg]');if(!b)return;s.background=b.dataset.bg;document.querySelectorAll('[data-bg]').forEach(x=>x.classList.toggle('selected',x===b))};el('#skillOptions').onclick=e=>{let b=e.target.closest('[data-skill]');if(!b)return;let a=s.skills.slice();if(a.includes(b.dataset.skill))a=a.filter(x=>x!==b.dataset.skill);else if(a.length<2)a.push(b.dataset.skill);else toast('Choose exactly two practiced skills.');s.skills=a;document.querySelectorAll('[data-skill]').forEach(x=>x.classList.toggle('selected',a.includes(x.dataset.skill)))};el('#createChar').onclick=()=>{let name=el('#charName').value.trim();if(!name){toast('Give your wayfarer a name first.');el('#charName').focus();return}if(s.skills.length!==2){toast('Choose two practiced skills.');return}s.name=name;s.created=true;s.location=0;s.stats={...baseStats};let bonuses={Elf:{DEX:2,INT:1},Dwarf:{CON:2,WIS:1},Halfling:{CHA:2,DEX:1},Orc:{STR:2,CON:1},Tiefling:{CHA:2,INT:1}};if(bonuses[s.ancestry])Object.entries(bonuses[s.ancestry]).forEach(([k,v])=>s.stats[k]+=v);else{s.stats.WIS++;s.stats.CHA++}s.log=[];pushLog('arrival',`${s.name}, a ${s.ancestry.toLowerCase()} ${s.background.toLowerCase()}, arrived in Brackenmere.`);el('#modalRoot').innerHTML='';render();toast('Your chronicle begins.')};};
