.dataset.action==='use'){if(i.qty>1)i.qty--;else s.inventory=s.inventory.filter(x=>x!==i);gainXP(5);toast('A little restored strength.')}else{i.equipped=!i.equipped;toast(i.equipped?`${i.name} equipped.`:`${i.name} put away.`)}render();return}let sell=e.target.closest('[data-sell]');if(sell){let i=s.inventory.find(x=>x.id===sell.dataset.sell);if(i){s.gold+=Math.max(1,Math.floor(i.value*.7));if(i.qty>1)i.qty--;else s.inventory=s.inventory.filter(x=>x!==i);toast(`Sold ${i.name}.`);render()}return}let buy=e.target.closest('[data-buy]');if(buy){let stock={bread:{...items[2],price:3},thread:{id:'thread',name:'Silver-thread spool',icon:'⌁',desc:'A length of shimmering thread. A favor to the right person.',type:'trade',value:9,price:8},tonic:{id:'tonic',name:'Bitterroot tonic',icon:'⚗',desc:'Restores your strength after a hard day.',type:'food',value:7,price:6}}[buy.dataset.buy];if(s.gold<stock.price){toast('Not enough silver marks.');return}s.gold-=stock.price;let found=s.inventory.find(x=>x.id===stock.id);if(found)found.qty++;else s.inventory.push({...stock,qty:1,equipped:false});toast(`${stock.name} added to your pack.`);render()}}}
