function renderWorld(){let joined=s.joined||[];el('#mainContent').innerHTML=`<div class="welcome-line"><div class="location">THE GREENMARCH · REALMS & POWERS</div><span class="day">An interconnected world</span></div><section class="panel view-panel"><div class="eyebrow">The powers that shape the realm</div><h2 style="margin-top:6px">Governments & gods</h2><p>The Greenmarch is held by the March Council, a compact of village stewards under Duchess Elowen’s distant rule. The crown’s writ thins with every mile from the capital.</p>${gods.map((g,i)=>`<div class="list-row"><div class="item-icon">${['♨','✧','✿','◉'][i]}</div><div class="list-copy"><div class="list-title">${g[0]}</div><div class="list-desc">${g[1]}</div></div>${s.offering===g[0]?'<span class="chip">Known to you</span>':`<button class="action-btn" data-offer="${i}">Offer a prayer</button>`}</div>`).join('')}</section><section class="panel view-panel"><div class="eyebrow">Find your people</div><h2 style="margin-top:6px">Guilds & hidden doors</h2><p>Public guilds welcome curious hands. Secret societies reveal themselves only to those who notice the signs—or earn someone’s trust.</p>${guilds.map(g=>{let known=g.type==='Public'||s.deeds.lore>=2||s.deeds.social>=3;let member=joined.includes(g.id);return `<div class="list-row"><div class="item-icon">${known?g.icon:'?'}</div><div class="list-copy"><div class="list-title">${known?g.name:'An unmarked circle'} <span class="chip">${known?g.type:'Secret'}</span></div><div class="list-desc">${known?g.desc:'You notice a repeating symbol among the old records. More may be revealed as you explore.'}</div></div>${known?(member?'<span class="chip">Member</span>':`<button class="action-btn" data-guild="${g.id}">Join</button>`):'<span class="quiet">Undiscovered</span>'}</div>`}).join('')}</section><section class="panel view-panel"><div class="eyebrow">A living economy</div><h2 style="margin-top:6px">The market remembers</h2><p>Local prices shift with scarcity, season, and trust. Trade with the villagers from your <button class="link-btn" data-goto="inventory">inventory</button>. A generous deed may open a better bargain than a full purse.</p></section>`;el('#mainContent').onclick=e=>{let b=e.target.closest('[data-guild]');if(b){let g=guilds.find(x=>x.id===b.dataset.guild);s.joined.push(g.id);pushLog('faction',`You joined ${g.name}.`);gainXP(15);toast(`Joined ${g.name}.`);render()}let o=e.target.closest('[data-offer]');if(o){let g=gods[+o.dataset.offer][0];s.offering=g;s.deeds.faith=(s.deeds.faith||0)+1;s.gold=Math.max(0,s.gold-1);s.relations.Rowan=Math.min(5,(s.relations.Rowan||0)+1);gainXP(12);pushLog('faith',`You left a silver mark for ${g}.`);toast('Your offering is remembered.');render()}if(e.target.closest('[data-goto]')){s.tab='inventory';render()}}}

