const places=[{name:'Brackenmere',region:'Village crossroads',icon:'⌂'},{name:'The Reed & Rook',region:'Common room',icon:'♨'},{name:'The Old Causeway',region:'North road',icon:'⌖'},{name:'The Lantern Shrine',region:'Sacred ground',icon:'☼'},{name:'The Lanternwood',region:'Deepwood',icon:'✿'}];
const merchantTypes={0:[{id:'brin-shop',name:'Brin’s Pantry',kind:'grocer',icon:'◒',categories:['grocer']},{id:'elin-shop',name:'Elin’s Stillroom',kind:'apothecary',icon:'⚗',categories:['apothecary']},{id:'tovin-shop',name:'Ashdown Forge',kind:'blacksmith',icon:'⚒',categories:['weapon','armor']},{id:'general-shop',name:'Old Nera’s General Goods',kind:'general store',icon:'▣',categories:['general']}],1:[{id:'inn-shop',name:'Innkeeper’s Provision Shelf',kind:'provisions',icon:'♨',categories:['grocer','general']}],3:[{id:'shrine-shop',name:'Shrine Herb Table',kind:'herbalist',icon:'✿',categories:['apothecary']}]};
const rarityOdds=[['Common',.54],['Uncommon',.27],['Rare',.13],['Epic',.05],['Legendary',.01]],rarityData={Common:[1,1,1],Uncommon:[1.2,1.3,1.5],Rare:[1.55,1.8,2.4],Epic:[2.15,2.5,4],Legendary:[3.5,3.8,8]},rarityWords={Common:'',Uncommon:'Fine ',Rare:'Masterwork ',Epic:'Enchanted ',Legendary:'Mythic '};
function generateItem(category,seed='world'){let pool=itemBases[category]||itemBases.general,base=pool[Math.floor(Math.random()*pool.length)],rarity='Common',r=Math.random(),sum=0;for(const [name,chance]of rarityOdds){sum+=chance;if(r<=sum){rarity=name;break}}let [name,icon,desc,value,requirement,type]=base,[priceMult,duraMult,weightMult]=rarityData[rarity],durability=Math.round((type==='consumable'||type==='food'?1:18)*duraMult),weight=+(category==='armor'?2.4:category==='weapon'?1.5:category==='grocer'?.45:.7)*weightMult;let special=rarity==='Common'?'':rarity==='Uncommon'?' Better balanced and unusually well made.':rarity==='Rare'?' It bears a maker’s mark no local smith claims.':rarity==='Epic'?' Faint old magic gathers along its edge.':' It carries a name from the oldest songs.';return{id:`${seed}-${Math.random().toString(36).slice(2,8)}`,name:rarityWords[rarity]+name,icon,desc:desc+special,type:type==='consumable'?'potion':type,category,qty:1,equipped:false,value:Math.max(1,Math.round(value*priceMult)),price:Math.max(1,Math.round(value*priceMult*1.35)),weight,durability,maxDurability:durability,requirement,rarity}}
function makeStock(shop){let stock=[];for(let i=0;i<4;i++){let cat=shop.categories[i%shop.categories.length];stock.push(generateItem(cat,shop.id))}return stock}
function storesAt(place=s.location){return merchantTypes[place]||[]}
