 function render(){save();if(!s.created){renderCreator();return}updateShell();if(s.tab==='chronicle')renderChronicle();else if(s.tab==='character')renderCharacter();else if(s.tab==='quests')renderQuests();else if(s.tab==='inventory')renderInventory();else renderWorld();renderRight()}
 function updateShell(){el('#sideName').textContent=s.name;el('#sideOrigin').textContent=`${s.ancestry} · ${s.background}`;el('#sideLevel').textContent=`Level ${s.level} · ${s.vocation||'Unclassed'}`;el('#sideXp').textContent=`${s.xp} / ${xpNeed()} XP`;el('#sideXpBar').style.width=`${Math.min(100,s.xp/xpNeed()*100)}%`;el('#levelTiny').textContent=`Level ${s.level+1}`;el('#headerDay').textContent=`✧ ${dayName(s.day)}`;document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===s.tab));el('#questBadge').textContent=s.quests.filter(q=>!q.done).length||'✓';}
 function dayName(d){let names=['First day of Thaw','Second day of Thaw','Third day of Thaw','Fourth day of Thaw','Fifth day of Thaw'];return names[(d-1)%5]+(d>5?` · Day ${d}`:'')}
 function renderCreator(){el('#rightbar').innerHTML='';el('#mainContent').innerHTML='<div style="height:45vh;min-height:300px;display:grid;place-items:center;text-align:center"><div><div class="sigil" style="margin:auto;width:58px;height:58px;font-size:28px">✦</div><div class="eyebrow" style="margin-top:20px">A world waiting to be changed</div><h1 style="font:600 34px var(--serif);margin:8px 0">Every legend begins<br>with a choice.</h1><p style="color:var(--muted);font:14px var(--serif);max-width:400px;line-height:1.6">There are no destinies here—only the life you choose to lead.</p><button class="primary" onclick="openCreator()" style="margin-top:14px">Begin your chronicle →</button></div></div>';}
-window.openCreator=()=>{el('#modalRoot').innerHTML=`<div class="modal-backdrop"><div class="modal"><div class="modal-kicker">The first page</div><h1>Who will you become?</h1><p class="modal-intro">Make a person, not a build. Your choices shape your gifts; your actions will reveal a calling in time.</p><label class="form-label">Name</label><input id="charName" type="text" maxlength="24" placeholder="What shall the world call you?" value="${esc(s.name||'')}"/><label class="form-label">Ancestry</label><div class="options" id="ancestryOptions">${Object.entries(ancestry).map(([k,v])=>`<button class="option ${s.ancestry===k?'selected':''}" data-ancestry="${k}">${k}<small>${v}</small></button>`).join('')}</div><label class="form-label">A life before the road</label><div class="options" id="backgroundOptions">${[['Wanderer','You learned by going.'],['Apprentice','You learned by making.'],['Acolyte','You learned by listening.'],['Courtier','You learned by reading a room.'],['Outcast','You learned to endure.']].map(([k,v])=>`<button class="option ${s.background===k?'selected':''}" data-bg="${k}">${k}<small>${v}</small></button>`).join('')}</div><label class="form-label">Choose two practiced skills</label><div class="options" id="skillOptions">${skills.map(x=>`<button class="option ${s.skills.includes(x)?'selected':''}" data-skill="${x}">${x}</button>`).join('')}</div><div class="modal-actions"><span>All paths begin at level 1. No class is chosen.</span><button class="primary" id="createChar">Enter the Greenmarch →</button></div></div></div>`;
+window.openCreator=()=>{el('#modalRoot').innerHTML=`<div class="modal-backdrop"><div class="modal"><div class="modal-kicker">The first page</div><h1>Who will you become?</h1><p class="modal-intro">Make a person, not a build. Your choices shape your gifts; your actions will reveal a calling in time.</p><label class="form-label">Name</label><input id="charName" type="text" maxlength="24" placeholder="What shall the world call you?" value="${esc(s.name||'')}"/><label class="form-label">Ancestry</label><div class="options" id="ancestryOptions">${Object.entries(ancestry).map(([k,v])=>`<button class="option ${s.ancestry===k?'selected':''}" data-ancestry="${k}">${k}<small>${v}</small></button>`).join('')}</div><label class="form-label">A life before the road</label><div class="options" id="backgroundOptions">${[['Wanderer','You learned by going.'],['Apprentice','You learned by making.'],['Acolyte','You learned by listening.'],['Courtier','You learned by reading a room.'],['Outcast','You learned to endure.']].map(([k,v])=>`<button class="option ${s.background===k?'selected':''}" data-bg="${k}">${k}<small>${v}</small></button>`).join('')}</div><div class="stat-buy-head"><label class="form-label">Spend your 27-point stat buy</label><span class="points-left" id="pointsLeft">${statPoints()} points left</span></div><p class="quiet">Scores 8–15 before ancestry. 14 costs 7 points; 15 costs 9. These shape checks, equipment access, and your approach.</p><div class="creator-stats" id="creatorStats">${Object.entries(s.statBuy||baseStats).map(([k,v])=>`<div class="buy-stat"><span>${k}</span><button type="button" data-stat="${k}" data-delta="-1" ${v<=8?'disabled':''}>−</button><strong>${v}</strong><button type="button" data-stat="${k}" data-delta="1" ${v>=15||statPoints()<=(v>=13?2:1)?'disabled':''}>+</button></div>`).join('')}</div><label class="form-label">Choose two practiced skills</label><div class="options" id="skillOptions">${skills.map(x=>`<button class="option ${s.skills.includes(x)?'selected':''}" data-skill="${x}">${x}</button>`).join('')}</div><div class="modal-actions"><span>All paths begin at level 1. No class is chosen.</span><button class="primary" id="createChar">Enter the Greenmarch →</button></div></div></div>`;
