--- function act(title ---
 function act(title,tag){let skillsBy={social:'Persuasion',explore:'Survival',faith:'Insight',craft:'Craft',lore:'Arcana',combat:'Athletics'};let skill=skillsBy[tag]||'Insight';let die=1+Math.floor(Math.random()*20),bonus=skillBonus(skill),dc=11,total=die+bonus,success=total>=dc;s.turn++;s.choiceCount++;s.day+=Math.random()<.25?1:0;s.deeds[tag]=(s.deeds[tag]||0)+1;let current=scenes[s.location%scenes.length];let outcomes={social:success?'Your honesty opens a door. Mara, the ferrymaster, shares what she knows—and asks you to keep it quiet.':'The answer comes guarded, but you catch a name: someone has been seen near the bell tower.',explore:success?'You follow the clue beyond the familiar paths. A curious little relic waits where the mist parts.':'The wild keeps its secret for now. Still, you notice a trail leading toward the Lanternwood.',faith:success?'The candle-flame steadies. For one breath, the shrine feels less like a ruin and more like a promise.':'The flame gutters, then burns on. Even unanswered prayers leave a mark.',craft:success?'A little care makes a real difference. The villagers notice—and someone presses a few coins into your hand.':'Your effort is appreciated, though the repair will take more work. A useful lesson, at least.',lore:success?'The old marks resolve into a name: Nym, the Unmoored Star. A fragment of amberglass warms in your palm.':'The marks resist easy reading. You copy them down; knowledge can wait.',combat:success?'You meet the danger with calm and clear purpose. The way ahead opens.':'You keep your footing and avoid the worst of it. The road is still yours.'};let text=outcomes[tag]||'The moment unfolds in a way only you could have set in motion.';if(success&&tag==='explore'&&!s.inventory.some(i=>i.id==='wildflower'))s.inventory.push({id:'wildflower',name:'Moonlit wildflower',icon:'✿',desc:'A pale bloom that only opens after dusk.',type:'herb',value:5,qty:1});if(success&&tag==='craft'){s.gold+=3;text+=' (+3 silver marks)'}if(tag==='social'){s.relations.Mara=Math.min(5,(s.relations.Mara||0)+(success?1:0));if(s.quests[0]&&!s.quests[0].done)s.quests[0].progress=Math.min(3,s.quests[0].progress+1)}if(tag==='lore'||tag==='explore'){if(s.quests[0]&&!s.quests[0].done)s.quests[0].progress=Math.min(3,s.quests[0].progress+1)}if(s.quests[0]&&s.quests[0].progress>=s.quests[0].total&&!s.quests[0].done){s.quests[0].done=true;s.gold+=s.quests[0].reward;text+=` Quest complete: “${s.quests[0].name}.” (+${s.quests[0].reward} silver marks)`;gainXP(40)}gainXP(success?25:12);if(s.turn%3===0){s.location=(s.location+1)%scenes.length;s.day++}s.lastNarration=text;pushLog(tag,text);s.rollText=`${skill} check: d20 ${die} ${bonus>=0?'+':''}${bonus} = ${total} vs DC ${dc} · ${success?'Success':'A complication'}. ${text}`;earned();render();}


