function act(title,tag){let skillsBy={social:'Persuasion',explore:'Survival',faith:'Insight',craft:'Craft',lore:'Arcana',combat:'Athletics'};
let skill=skillsBy[tag]||'Insight';
let die=1+Math.floor(Math.random()*20),bonus=skillBonus(skill),dc=11,total=die+bonus,success=total>=dc;
s.turn++;
s.choiceCount++;
s.day+=Math.random()<.25?1:0;
s.deeds[tag]=(s.deeds[tag]||0)+1;
let current=scenes[s.location%scenes.length];
let outcomes={social:success?`Your ${title.toLowerCase()} meets a warmer answer than expected at ${current.name}.`:`Your ${title.toLowerCase()} is met with reserve in ${current.name};
 a detail in the reply stays with you.`,explore:success?`Your choice draws you into ${current.name};
 a small discovery alters how the place looks.`:`The place holds back its secret. Your attention catches details others might miss.`,faith:success?`Your gesture settles the air around ${current.name};
 the old flame steadies for a breath.`:`The ritual leaves no clear answer, though its silence feels changed.`,craft:success?`Your work holds. Someone nearby notices the care in it and leaves 3 silver marks.`:`The attempt does not hold together, but the materials reveal where the strain lies.`,lore:success?`The old marks yield a name: Nym, the Unmoored Star. Amberglass warms in your palm.`:`The marks resist easy reading. Your notes preserve what the stone would not give.`,combat:success?`You meet the danger with clear purpose;
 the immediate threat is driven back.`:`You keep your footing through the clash, though the threat remains unresolved.`};
let text=outcomes[tag]||'The moment unfolds in a way only you could have set in motion.';
if(success&&tag==='explore'&&!s.inventory.some(i=>i.id==='wildflower'))s.inventory.push({id:'wildflower',name:'Moonlit wildflower',icon:'✿',desc:'A pale bloom that only opens after dusk.',type:'herb',value:5,qty:1});
if(success&&tag==='craft'){s.gold+=3;
text+=' (+3 silver marks)'}if(tag==='social'){s.relations.mara=Math.min(5,(s.relations.mara||0)+(success?1:0));
s.npcs.mara??={talks:0};
s.npcs.mara.talks++;
s.npcs.mara.memory=`You ${success?'earned a little trust':'left the conversation unresolved'} with Mara on day ${s.day}. She remembers who pays their fare and who helps at the landing.`;
if(s.quests[0]&&!s.quests[0].done)s.quests[0].progress=Math.min(3,s.quests[0].progress+1)}if(tag==='lore'||tag==='explore'){if(s.quests[0]&&!s.quests[0].done)s.quests[0].progress=Math.min(3,s.quests[0].progress+1)}if(s.quests[0]&&s.quests[0].progress>=s.quests[0].total&&!s.quests[0].done){s.quests[0].done=true;
s.gold+=s.quests[0].reward;
text+=` Quest complete: “${s.quests[0].name}.” (+${s.quests[0].reward} silver marks)`;
gainXP(40)}gainXP(success?25:12);
if(s.turn%3===0){s.location=(s.location+1)%scenes.length;
s.day++}s.lastNarration=text;
pushLog(tag,text);
s.rollText=`${skill} check: d20 ${die} ${bonus>=0?'+':''}${bonus} = ${total} vs DC ${dc} · ${success?'Success':'A complication'}. ${text}`;
earned();
render();
}

