const assert=require('node:assert/strict');
(async()=>{
 const browser=await chromium.launch({headless:true}); const page=await browser.newPage({viewport:{width:1440,height:1000}}); const errors=[]; page.on('pageerror',e=>errors.push(e.message));
 await page.goto('http://127.0.0.1:3000/'); await page.evaluate(()=>localStorage.clear()); await page.reload();
 await page.getByRole('button',{name:/Begin your chronicle/}).click();
 await page.locator('#charName').fill('Mira Vale');
 for(let i=0;i<3;i++) await page.locator('[data-stat="WIS"][data-delta="1"]').click();
 assert.match(await page.locator('#pointsLeft').textContent(),/24 points left/);
 await page.locator('#createChar').click();
 assert.equal(await page.locator('#sideName').textContent(),'Mira Vale');
 assert.equal((await page.locator('[data-npc="mara"]').count())>0,true);
 await page.screenshot({path:'/tmp/opencode/hollowmere-gameplay.png',fullPage:true});
 // NPC relationship, memory, conditional recruitment
 await page.locator('[data-npc="mara"][data-npc-action="listen"]').click();
 await page.locator('[data-npc="mara"][data-npc-action="share"]').click();
 assert.equal(await page.evaluate(()=>JSON.parse(localStorage.getItem('hollowmere_v1')).relations.mara),3);
 assert.equal(await page.locator('[data-npc="mara"][data-npc-action="invite"]').count(),1);
 await page.locator('[data-npc="mara"][data-npc-action="invite"]').click();
 assert.equal(await page.evaluate(()=>JSON.parse(localStorage.getItem('hollowmere_v1')).joined.includes('npc:mara')),true);
 // Inventory consume and local merchant buy
 await page.locator('[data-tab="inventory"]').first().click();
 await page.locator('[data-item="bread"]').click();
 let state=await page.evaluate(()=>JSON.parse(localStorage.getItem('hollowmere_v1')));
 assert.equal(state.inventory.find(i=>i.id==='bread').qty,1);
 await page.locator('[data-visit="brin-shop"]').click();
 assert.equal(await page.locator('[data-buy]').count(),4);
 const stockMeta=await page.locator('[data-buy]').first().locator('xpath=..').textContent();
 await page.locator('[data-buy]').first().click();
 state=await page.evaluate(()=>JSON.parse(localStorage.getItem('hollowmere_v1')));
 assert.equal(state.shops['brin-shop'].length,3);
 assert.equal(state.inventory.length,4);
 assert.ok(state.inventory.at(-1).rarity && typeof state.inventory.at(-1).weight==='number');
 // Three meaningful actions advance to inn, with its own stock
 await page.locator('[data-tab="chronicle"]').first().click();
 for(let i=0;i<3;i++) await page.locator('[data-choice]').first().click();
 state=await page.evaluate(()=>JSON.parse(localStorage.getItem('hollowmere_v1')));
 assert.equal(state.location,1);
 await page.locator('[data-tab="inventory"]').first().click();
 assert.equal(await page.locator('[data-visit="inn-shop"]').count(),1);
 assert.equal(await page.locator('[data-visit="tovin-shop"]').count(),0);
 // Reload save migration/persistence
 await page.reload();
 assert.equal(await page.locator('#sideName').textContent(),'Mira Vale');
 assert.equal(await page.evaluate(()=>JSON.parse(localStorage.getItem('hollowmere_v1')).location),1);
 assert.deepEqual(errors,[]);
 console.log(JSON.stringify({created:true,statBuy:'27-point pool validated',npcRecruitment:true,inventoryUse:true,merchantPurchase:true,locationSpecificShop:true,locationProgression:true,reloadPersistence:true,pageErrors:errors,screenshot:'/tmp/opencode/hollowmere-gameplay.png'},null,2));
 await browser.close();
})().catch(e=>{console.error(e);process.exit(1)});
NODE
